 out=D/'fclones-walk-review-20261012.json';assert not out.exists();out.write_text(json.dumps({'status':'verified_targeted_walk_and_lock_review_not_complete_tree','commit':m['commit'],'fully_read_additional_files':{'fclones/src/walk.rs':675,'fclones/src/lock.rs':90},'upstream_walk_tests_passed':10,'filtered_not_passed':157,'tests':sorted(names),'pins':{str(p):sha(p)for p in [mp,upstream,b,log,Path(__file__)]},'findings':[{'kind':'source_observation','location':'fclones/src/walk.rs:420','detail':'sorted_entries collects the entire directory before sorting and queues a Rayon task per entry. No per-directory managed byte/entry admission in this function; this is not a measured process-memory bound.'},{'kind':'source_observation','location':'fclones/src/walk.rs:420','detail':'ReadDir and DirEntry conversion errors are discarded by filter_map in sorted_entries. Top-level stat/read_dir errors separately reach optional logger.'},{'kind':'source_observation','location':'fclones/src/lock.rs:35','detail':'Unix F_SETLK is advisory; it is not evidence that unrelated writers cannot modify a scanned file. Windows branch was read but not executed.'}],'scope':'Original preserved upstream binary executes10 existing walk cases including directory cycles, symlink targets, reporting links, hidden paths and ignore files. No new upstream regression, concurrent writer control, memory measurement, Windows execution or full42file/full500 review. No code adopted.'},indent=2)+'\n');print('Verified ten original walk tests; walk.rs and lock.rs fully read; no adoption')
